package mapdata

import (
	"bytes"
	"context"
	"encoding/binary"
	"encoding/hex"
	"encoding/json"
	"os"
	"testing"
)

func TestIndependentLZ4AndXXHashVectors(t *testing.T) {
	// Values generated by system libxxhash (primary C implementation), not Go decoder.
	for _, v := range []struct {
		data       string
		seed, want uint32
	}{{"", 0, 0x02cc5d05}, {"a", 0, 0x550d7456}, {"abc", 0, 0x32d153ff}} {
		if got := xxh32([]byte(v.data), v.seed); got != v.want {
			t.Fatalf("hash %q: %08x", v.data, got)
		}
	}
	b, e := os.ReadFile("testdata/lz4-oracle.bin")
	if e != nil {
		t.Fatal(e)
	}
	got, e := decompress(context.Background(), 4, b)
	if e != nil {
		t.Fatal(e)
	}
	want, e := os.ReadFile("testdata/1.20.5-modern.nbt")
	if e != nil {
		t.Fatal(e)
	}
	if !bytes.Equal(got, want) {
		t.Fatal("independent C-compressed frame did not match NBT")
	}
	for _, pos := range []int{0, 8, 9, 13, 17, 22, len(b) - 1} {
		bad := bytes.Clone(b)
		bad[pos] ^= 0xff
		if _, e := decompress(context.Background(), 4, bad); e == nil {
			t.Fatalf("frame tamper accepted at %d", pos)
		}
	}
	if _, e := decompress(context.Background(), 4, b[:len(b)-1]); e == nil {
		t.Fatal("truncated frame accepted")
	}
	// Hand-framed raw block, exact checksum from libxxhash, raw encoding little endian.
	raw, _ := hex.DecodeString("4c5a34426c6f636b10030000000300000000000000")
	binary.LittleEndian.PutUint32(raw[17:], 0x32d153ff) // checked separately above, seed zero differs: this stream must fail default-seed check.
	if _, e := decompress(context.Background(), 4, append(raw, []byte("abc")...)); e == nil {
		t.Fatal("wrong seeded checksum accepted")
	}
}

func TestAllPrimaryCSeededXXHashVectors(t *testing.T) {
	b, e := os.ReadFile("testdata/xxhash-vectors.json")
	if e != nil {
		t.Fatal(e)
	}
	var vectors []struct {
		Hex       string
		Seed, Sum uint32
	}
	if e := json.Unmarshal(b, &vectors); e != nil {
		t.Fatal(e)
	}
	if len(vectors) != 15 {
		t.Fatal("incomplete C oracle vectors")
	}
	for i, v := range vectors {
		input, e := hex.DecodeString(v.Hex)
		if e != nil {
			t.Fatal(e)
		}
		if got := xxh32(input, v.Seed); got != v.Sum {
			t.Fatalf("oracle %d seed%08x len%d: %08x want%08x", i, v.Seed, len(input), got, v.Sum)
		}
	}
}
